    var ChartManager = {
      charts: new Map(),
      safeInit: function (canvasId, config) {
        if (typeof Chart === 'undefined') {
          console.error('Chart.js library not loaded - check CDN inclusion');
          return null;
        }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var ctx = document.getElementById(canvasId);
          if (!ctx) {
            console.error('Canvas element not found: ' + canvasId);
            return null;
          }
          if (ctx.chart) {
            ctx.chart.destroy();
            delete ctx.chart;
          }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) {
            ctx.setAttribute('aria-label', 'Chart visualization');
          }
          var chart = new Chart(ctx, config);
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) {
          console.error('Chart initialization failed for ' + canvasId + ':', error);
          return null;
        }
      },
      updateTheme: function () {
        if (typeof Chart === 'undefined') return;
        this.charts.forEach(function (chart) {
          try { chart.update(); } catch (error) { console.error('Chart theme update failed:', error); }
        });
      }
    };

    function getVar(name) {
      return getComputedStyle(document.body).getPropertyValue(name).trim();
    }

    function initCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }

      ChartManager.safeInit('methodChart', {
        type: 'doughnut',
        data: {
          labels: ['Academic Reputation 40%', 'Faculty/Student Ratio 20%', 'Citations/Faculty 20%', 'Employer Reputation 10%', 'International Faculty 5%', 'International Students 5%'],
