            borderColor: getVar('--surface'),
            borderWidth: 2
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { tooltip: { enabled: true }, legend: { labels: { color: getVar('--text'), boxWidth: 12 } } }
        }
      });

      ChartManager.safeInit('regionChart', {
        type: 'bar',
        data: {
          labels: ['Europe', 'North America', 'Asia-Pacific', 'Middle East & Africa', 'Latin America'],
          datasets: [{
            label: 'Universities in Top 100',
            data: [38,30,26,4,2],
            backgroundColor: [getVar('--accent'), '#60a5fa', getVar('--accent-secondary'), '#f59e0b', '#f87171']
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { tooltip: { enabled: true }, legend: { labels: { color: getVar('--text') } } },
          scales: {
            x: { ticks: { color: getVar('--text-secondary') }, grid: { color: 'rgba(255,255,255,0.08)' } },
            y: { beginAtZero: true, ticks: { color: getVar('--text-secondary') }, grid: { color: 'rgba(255,255,255,0.08)' } }
          }
        }
      });
    }

    function toggleMenu() {
      document.getElementById('vizMenu').classList.toggle('open');
    }

    function toggleTheme() {
      var body = document.body;
      body.classList.toggle('theme-dark');
      body.classList.toggle('theme-light');
      ChartManager.updateTheme();
      initCharts();
    }

    function downloadImage() {
      var node = document.getElementById('main-content');
      var opts = { pixelRatio: 2, backgroundColor: getVar('--bg') || '#0b1d3a' };
      htmlToImage.toPng(node, opts).then(function (dataUrl) {
        var link = document.createElement('a');
        link.download = 'final_poster.png';
        link.href = dataUrl;
        link.click();
      }).catch(function (error) {
        console.error('PNG export failed:', error);
      });
    }

